    async def on_replace_merged_instrument(self, heard: Heard[ops.InstrumentReplacedEvent]) -> None:
        """W3.8: A deployment's record was replaced by another (W3.8): from contract v10, a
        record a person merged into the one that stays (W3.13); before it, a placeholder by its
        INS- ID. Optional: heard only where a class overrides it."""

    async def on_account_attribute_changed(self, heard: Heard[ops.AccountAttributeChangedEvent]) -> None:
        """W9.8: AccountAttributeChanged. Optional: heard only where a class overrides it."""

    @abstractmethod
    async def on_order_updated(self, heard: Heard[ops.OrderUpdatedEvent]) -> None:
        """W11.13: OrderUpdated. Required: the ems suite's `claims-a-released-order` expects it
        heard."""

    @abstractmethod
    async def on_placement_updated(self, heard: Heard[ops.PlacementUpdatedEvent]) -> None:
        """W11.13: To the `ems`, `oms` and `compliance` within scope, and to the connectivity
        plugin it names, alone of its role (matrix/directed.tsv). Required: the ems suite's
        `agent-placement-on-a-demo-connection` expects it heard."""

    @abstractmethod
    async def on_execution_recorded(self, heard: Heard[ops.ExecutionRecordedEvent]) -> None:
        """W11.13: W9's PositionChanged follows for each position it moved. Required: the ems
        suite's `accepts-a-fill-to-an-order` expects it heard."""

    async def on_trading_instruction_changed(self, heard: Heard[ops.TradingInstructionChangedEvent]) -> None:
        """W11.16: To every subscriber, without an account scope. Optional: heard only where a
        class overrides it."""

    async def on_report_venue_catalogue(self, heard: Heard[ops.VenueCatalogueEvent]) -> None:
        """W11.20: W11.20. Optional: heard only where a class overrides it."""

    async def on_trades_recorded(self, heard: Heard[ops.TradesRecordedEvent]) -> None:
        """W10.5: A trade the lake recorded, on its dataset's subject (contract v19). Optional:
        heard only where a class overrides it."""

    async def on_quotes_recorded(self, heard: Heard[ops.QuotesRecordedEvent]) -> None:
        """W10.5: A quote the lake recorded, on its dataset's subject (contract v19). Optional:
        heard only where a class overrides it."""

    async def on_event_group_changed(self, heard: Heard[ops.EventGroup]) -> None:
        """W3.30: An event's group of contracts, at a version. Optional: heard only where a
        class overrides it."""

    async def on_liveness_recorded(self, heard: Heard[ops.LivenessRecordedEvent]) -> None:
        """W10.5: A dataset's liveness, on its subject: conflated per dataset and venue.
        Optional: heard only where a class overrides it."""

    async def on_series_recorded(self, heard: Heard[ops.SeriesRecordedEvent]) -> None:
        """W10.5: Contract v28, amended 2026-10-30 (W10.5; spec/one-data-access-model, step 2;
        rulings 847 and 886): a listed series the lake recorded, new or the next version of its
        key, on its dataset's subject, heard by ListSeries' askers so a copy of a chain follows
        its listing. Optional: heard only where a class overrides it."""
